import{_ as o,o as e,c as t,a2 as i}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"Form Builder & Custom Order Fields","description":"","frontmatter":{},"headers":[],"relativePath":"admin/form-builder.md","filePath":"admin/form-builder.md"}'),a={name:"admin/form-builder.md"};function s(l,r,d,n,m,c){return e(),t("div",null,[...r[0]||(r[0]=[i('<h1 id="form-builder-custom-order-fields" tabindex="-1">Form Builder &amp; Custom Order Fields <a class="header-anchor" href="#form-builder-custom-order-fields" aria-label="Permalink to &quot;Form Builder &amp; Custom Order Fields&quot;">​</a></h1><p>The Form Builder (<code>/form-builder</code>) allows administrators to design dynamic custom input forms attached to specific products or checkout flows.</p><hr><h2 id="📝-creating-custom-forms" tabindex="-1">📝 Creating Custom Forms <a class="header-anchor" href="#📝-creating-custom-forms" aria-label="Permalink to &quot;📝 Creating Custom Forms&quot;">​</a></h2><ol><li>Go to <strong>Form Builder</strong> in the Administrator Portal.</li><li>Click <strong>Create Form</strong> (e.g., <code>Dedicated Server Custom Options</code> or <code>Domain Extra Info</code>).</li><li>Add Fields: <ul><li><strong>Text / Textarea:</strong> For server hostnames, root passwords, or custom instructions.</li><li><strong>Select / Dropdown:</strong> For Operating System choices (Ubuntu 24.04, Debian 12, AlmaLinux 9).</li><li><strong>Checkbox / Radio:</strong> For add-on backups or control panel licenses.</li></ul></li><li>Set validation rules (Required, regex patterns, minimum/maximum lengths).</li><li>Attach the form to a product in <strong>Products &amp; Catalog</strong>. During checkout, the client portal will dynamically render these fields.</li></ol>',5)])])}const f=o(a,[["render",s]]);export{p as __pageData,f as default};
